import{_ as a,o,c as t,a2 as s}from"./chunks/framework.D3GK3dQI.js";const h=JSON.parse('{"title":"ADR-002: Gateway Address Resolution","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/002-ip-resolution.md","filePath":"adrs/002-ip-resolution.md"}'),r={name:"adrs/002-ip-resolution.md"};function i(d,e,n,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-002-gateway-address-resolution" tabindex="-1">ADR-002: Gateway Address Resolution <a class="header-anchor" href="#adr-002-gateway-address-resolution" aria-label="Permalink to &quot;ADR-002: Gateway Address Resolution&quot;">​</a></h1><p><strong>Date:</strong> 2026-06-06<br><strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The <code>exposed_route_info</code> metric includes an <code>ip_address</code> label. Gateway API already defines the portable source for this value in <code>Gateway.status.addresses</code>.</p><p>Cloud-provider API lookups would require provider-specific SDKs, credentials, naming assumptions, and additional failure handling. An allocated cloud address also does not prove that a Gateway or Route is ready to serve traffic.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The exporter reads the first address whose type is <code>IPAddress</code> from <code>Gateway.status.addresses</code>.</p><p>When no IP address is present, the exporter emits the exposure relationship with <code>ip_address=&quot;&quot;</code>. Route inventory therefore remains available while the Gateway controller is provisioning infrastructure.</p><p>The exporter does not query cloud-provider APIs and does not require cloud IAM permissions.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The implementation remains portable across Gateway API controllers and cloud providers.</li><li>The metric can describe configured exposure before an address is allocated.</li><li>Address visibility follows the status update latency of the Gateway controller.</li><li>Hostname-type Gateway addresses are not copied into the <code>ip_address</code> label.</li></ul><h2 id="traceability" tabindex="-1">Traceability <a class="header-anchor" href="#traceability" aria-label="Permalink to &quot;Traceability&quot;">​</a></h2><p>Address extraction is implemented in <code>internal/kubernetes/mapper/mapper.go</code> and specified in <code>openspec/specs/ip-resolution/spec.md</code>.</p>',13)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
